      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉત્તર:</strong> કવિ માટે કૃષ્ણનું રૂપ માત્ર સુંદર જ નથી, પણ કલ્યાણકારી પણ છે. તેમના દર્શન કરવાથી ભક્તના તમામ દુઃખો દૂર થાય છે અને હૃદયને શાંતિ મળે છે. આથી, નરસિંહ મહેતા તેમને મંગલકારી કે શુભકારી સ્વામી કહે છે.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: જેનું રૂપ સુખ આપે તે ‘શુભકારી’.</p></div>"
