      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉત્તર:</strong> કૃષ્ણનું મનમોહક રૂપ કવિના હૃદયમાં વસ્યું છે. તેને કારણે કવિનું મન વેગથી કૃષ્ણને મળવા દોડ્યું છે અને તેઓ કૃષ્ણ પર વારંવાર ઓવારી જાય છે.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: રૂપ વસ્યું હૈયામાં, મન દોડ્યું મળવાને.</p></div>"
